DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.settle_appointment(uuid,jsonb,jsonb,boolean,text)'::regprocedure) INTO definition; definition:=replace(definition,'INSERT INTO public.billing_settlements(tenant_id', 'issuer:=issuer||jsonb_build_object(''invoiceDetails'',coalesce((SELECT jsonb_object_agg(key,value) FROM public.settings WHERE tenant_id=a.tenant_id AND key IN (''invoice_legal_name'',''invoice_address'',''invoice_tax_number'',''invoice_big'',''invoice_agb'')),''{}''::jsonb)); INSERT INTO public.billing_settlements(tenant_id'); EXECUTE definition; END $$;